node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const row = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'C4C633'\").get();
if (row) {
  console.log(JSON.stringify(row, null, 2));
} else {
  console.log('Reservation C4C633 not found');
  // List all booking IDs to check
  const all = db.prepare('SELECT booking_id FROM flight_bookings').all();
  console.log('Available reservations:', all.map(r => r.booking_id));
}
db.close();
"

