node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get flight FLE7F420 details
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FLE7F420'\").get();
if (flight) {
  console.log('=== Flight FLE7F420 ===');
  console.log(JSON.stringify(flight, null, 2));
  console.log();
  console.log('=== Dates JSON parsed ===');
  console.log(JSON.stringify(JSON.parse(flight.dates_json), null, 2));
} else {
  console.log('Flight FLE7F420 not found');
}

// Also check the return flight
const flight2 = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FL84B16B'\").get();
if (flight2) {
  console.log();
  console.log('=== Flight FL84B16B ===');
  console.log(JSON.stringify(flight2, null, 2));
  console.log();
  console.log('=== Dates JSON parsed ===');
  console.log(JSON.stringify(JSON.parse(flight2.dates_json), null, 2));
}

db.close();
"

